INSERT INTO hotels (id, name, location, image, is_available, rating, review_count, price_per_night, latitude, longitude, hotel_description, hotel_type_id, chain, currency, country, city, address, zip, main_photo, thumbnail, stars, facility_ids, accessibility_attributes, deleted_at) VALUES
('hotel-001', 'Hotel Lord Byron', 'Rome', 'https://static.cupid.travel/hotels/ex_73af06d5_z.jpg', true, 8.7, 123, 420.0, 41.919861, 12.481478, '<p>Experience the elegance of Hotel Lord Byron, an Art Deco gem nestled in the heart of Rome, where sophistication meets comfort.</p><p><strong>Luxurious Accommodations</strong><br>Relax in one of our 28 stylish guestrooms, featuring memory foam beds, premium bedding, and modern amenities such as LCD televisions and minibars. Each room is designed for your utmost comfort, with complimentary toiletries and high-speed wireless internet access.</p><p><strong>Gastronomic Delights</strong><br>Indulge in culinary excellence at our on-site restaurant, Sapori del Lord Byron, where you can enjoy a delightful menu paired with a sophisticated bar/lounge ambiance. Start your day with our complimentary buffet breakfast served daily, ensuring you are energized for your explorations.</p><p><strong>Exceptional Services</strong><br>Our attentive concierge services are at your disposal to tailor your experience, and we offer convenient amenities like dry cleaning, a 24-hour front desk, and wedding services to make your stay seamless.</p><p>Book your unforgettable escape at Hotel Lord Byron today!</p>', 204, 'Not Available', 'EUR', 'it', 'rome', 'Via De Notaris Giuseppe 5', '00197', 'https://static.cupid.travel/hotels/ex_73af06d5_z.jpg', 'https://static.cupid.travel/hotels/thumbnail/ex_73af06d5_z.jpg', 5, '[1054, 1091, 2020, 2050, 2247, 2253, 2259, 2261, 2411, 107, 8, 14, 91, 180, 124, 185, 491, 526, 529, 533, 542, 561, 564, 567, 581, 626, 730, 782, 784, 816, 827, 845, 846, 847, 848, 969, 970, 987, 988, 991, 992, 993, 994, 995, 996, 997, 998, 999, 1001, 1002, 1003, 1004, 1006, 1007, 1008, 1009, 1011, 1012, 1013, 1014]'::jsonb, '{"attributes": null, "showerChair": null, "entranceType": null, "petFriendly": "", "rampAngle": 0, "rampLength": 0, "entranceDoorWidth": 0, "roomMaxGuestsNumber": 0, "distanceFromTheElevatorToTheAccessibleRoom": 0}'::jsonb, NULL),
('hotel-002', 'Cardo Roma, Autograph Collection', 'Rome', 'https://static.cupid.travel/hotels/506824411.jpg', true, 8.8, 415, 310.0, 41.84214, 12.47213, '<p><strong>Luxurious Accommodation</strong><br>Cardo Roma, Autograph Collection in Rome offers a sophisticated stay with modern amenities. The rooms feature elegant decor, flat-screen TVs, and comfortable seating areas, ensuring a relaxing retreat for guests.</p><p><strong>Convenient Facilities</strong><br>Enjoy the convenience of a fitness centre, private parking, and a garden at the hotel. With a 24-hour front desk, room service, and a snack bar, guests can indulge in top-notch service throughout their stay.</p><p><strong>Delightful Dining Options</strong><br>Start your day with a delicious breakfast buffet offering American and gluten-free choices. Unwind at the in-house bar or savor a meal at the hotel''s restaurant. For those on the go, a coffee machine in the rooms ensures a quick caffeine fix.</p><p>Book your luxurious stay at Cardo Roma, Autograph Collection now for an unforgettable experience in Rome.</p>', 204, 'Autograph Collection', 'EUR', 'it', 'rome', 'Viale Del Pattinaggio 100', '00144', 'https://static.cupid.travel/hotels/506824411.jpg', 'https://static.cupid.travel/hotels/thumbnail/506824411.jpg', 4, '[2261, 6848, 16, 109, 301, 3, 5, 28, 4, 48, 91, 51, 25, 63, 73, 127, 170, 129, 124, 159, 185, 176, 183, 164, 222, 219, 205, 218, 256, 455, 451, 449, 462, 461, 425, 459, 467, 460, 465, 468, 422, 456, 466, 453, 454, 424, 486, 488, 418, 485, 421, 487, 463, 407, 409, 495, 521, 540, 626, 631, 675, 714, 725, 757, 761, 803, 809, 828, 835, 856, 857, 916, 995, 1003, 1021, 1022]'::jsonb, '{"attributes": null, "showerChair": null, "entranceType": null, "petFriendly": "", "rampAngle": 0, "rampLength": 0, "entranceDoorWidth": 0, "roomMaxGuestsNumber": 0, "distanceFromTheElevatorToTheAccessibleRoom": 0}'::jsonb, NULL),
('hotel-003', 'Crowne Plaza Rome St. Peter''s, an IHG Hotel', 'Rome', 'https://static.cupid.travel/hotels/247143313.jpg', true, 8.2, 2033, 260.0, 41.88884, 12.42573, '<p><strong>Luxurious Amenities</strong><br>Crowne Plaza Rome - St. Peter''s offers a haven of relaxation with a private park, spa services, tennis courts, and a refreshing outdoor pool with a pool bar for the ultimate unwind.</p><p><strong>Gastronomic Delights</strong><br>Indulge in delectable Italian cuisine at the on-site restaurant, open all day, and savor your meals on the terrace during the summer, creating a memorable dining experience.</p><p><strong>Convenience and Comfort</strong><br>Enjoy spacious rooms with modern décor, complimentary buffet breakfast, a 24-hour fitness center, and free parking, along with easy access to transportation options for exploring Rome effortlessly.</p><p>Experience luxury, comfort, and convenience at Crowne Plaza Rome - St. Peter''s. Book your stay now for an unforgettable Roman getaway.</p>', 204, 'Crowne Plaza Hotels & Resorts', 'EUR', 'it', 'rome', 'Via Aurelia Antica 415', '00165', 'https://static.cupid.travel/hotels/247143313.jpg', 'https://static.cupid.travel/hotels/thumbnail/247143313.jpg', 4, '[1814, 2083, 2413, 6848, 16, 109, 301, 3, 5, 28, 4, 48, 91, 51, 81, 78, 64, 25, 44, 63, 10, 55, 50, 129, 124, 185, 101, 176, 183, 188, 189, 222, 205, 218, 236, 241, 226, 231, 232, 256, 213, 455, 451, 449, 462, 457, 461, 425, 459, 467, 465, 468, 422, 456, 466, 453, 454, 424, 458, 464, 488, 418, 485, 421, 420, 463, 407, 495, 497, 521, 540, 584, 626, 631, 642, 669, 675, 691, 692, 720, 725, 757, 758, 761, 784, 806, 809, 828, 835, 856, 857, 859, 901, 916, 967, 1003, 1005, 1021, 1022, 1027, 1028]'::jsonb, '{"attributes": null, "showerChair": null, "entranceType": null, "petFriendly": "", "rampAngle": 0, "rampLength": 0, "entranceDoorWidth": 0, "roomMaxGuestsNumber": 0, "distanceFromTheElevatorToTheAccessibleRoom": 0}'::jsonb, NULL),
('hotel-004', 'Hotel Patria', 'Rome', 'https://static.cupid.travel/hotels/4881550.jpg', true, 8.2, 1830, 180.0, 41.9027, 12.49437, '<p><strong>Central Location and Convenience</strong><br>Hotel Patria is conveniently located near Piazza della Repubblica, offering easy access to main sites and the Termini Railway Station. Guests can walk to the Repubblica Metro Station in just 5 minutes, with restaurants, shops, and boutiques in close proximity.</p><p><strong>Comfortable Accommodation</strong><br>The hotel features cozy rooms equipped with modern amenities such as flat-screen TVs, en suite bathrooms, and air conditioning. The 24-hour front desk ensures that guests receive prompt assistance and the bar provides a perfect spot to unwind after a day of exploring the city.</p><p><strong>Helpful Services</strong><br>Hotel Patria goes the extra mile to assist guests with tourist information, sightseeing recommendations, and convenient airport transfers. Enjoy complimentary WiFi in the reception area and make the most of your stay with the friendly and accommodating hotel staff.</p><p>Experience the convenience and comfort of Hotel Patria - book your stay now!</p>', 204, 'Not Available', 'EUR', 'it', 'rome', 'Via Torino 36', '00184', 'https://static.cupid.travel/hotels/4881550.jpg', 'https://static.cupid.travel/hotels/thumbnail/4881550.jpg', 3, '[16, 109, 5, 4, 48, 91, 51, 81, 78, 53, 143, 124, 219, 205, 455, 451, 449, 462, 457, 461, 425, 459, 467, 460, 465, 468, 422, 456, 453, 419, 454, 458, 464, 418, 487, 420, 521, 540, 584, 626, 761, 784, 809, 857, 880, 1003]'::jsonb, '{"attributes": null, "showerChair": null, "entranceType": null, "petFriendly": "", "rampAngle": 0, "rampLength": 0, "entranceDoorWidth": 0, "roomMaxGuestsNumber": 0, "distanceFromTheElevatorToTheAccessibleRoom": 0}'::jsonb, NULL),
('hotel-005', 'Holiday Inn Rome - Eur Parco Dei Medici, an IHG Hotel', 'Rome', 'https://static.cupid.travel/hotels/246613041.jpg', true, 7.8, 4389, 220.0, 41.82319, 12.41219, '<p><strong>Luxurious Accommodations</strong><br>Holiday Inn Rome offers air-conditioned rooms with modern amenities including a 32&quot; LCD TV and private bathrooms. Some rooms even come with a minibar and safe for your convenience.</p><p><strong>Delicious Dining Options</strong><br>Start your day with an American buffet breakfast and savor Mediterranean and international cuisine at La Serra Restaurant. Enjoy a refreshing drink at the Incontro lounge bar or by the poolside during summer.</p><p><strong>Convenient Location and Services</strong><br>Located in the business district, the hotel is close to Muratella Train Station and offers a shuttle service to Fiumicino Airport and the city center. With a swimming pool, free WiFi, and private parking, Holiday Inn Rome ensures a comfortable stay for all guests.</p><p>Experience luxury and convenience at Holiday Inn Rome - Eur Parco Dei Medici. Book now for an unforgettable stay!</p>', 204, 'Holiday Inn Hotels & Resorts', 'EUR', 'it', 'rome', 'Viale Castello Della Magliana 65', '00148', 'https://static.cupid.travel/hotels/246613041.jpg', 'https://static.cupid.travel/hotels/thumbnail/246613041.jpg', 4, '[2413, 6848, 16, 109, 301, 3, 5, 15, 28, 4, 48, 91, 51, 81, 25, 44, 10, 58, 53, 108, 143, 129, 124, 101, 176, 173, 183, 193, 222, 219, 200, 455, 451, 449, 462, 457, 461, 425, 459, 467, 465, 468, 422, 466, 454, 424, 486, 485, 421, 487, 420, 495, 521, 540, 584, 626, 631, 642, 652, 675, 708, 712, 714, 757, 761, 784, 809, 828, 835, 856, 857, 859, 916, 967, 1003, 1021, 1022, 1027, 1028]'::jsonb, '{"attributes": null, "showerChair": null, "entranceType": null, "petFriendly": "", "rampAngle": 0, "rampLength": 0, "entranceDoorWidth": 0, "roomMaxGuestsNumber": 0, "distanceFromTheElevatorToTheAccessibleRoom": 0}'::jsonb, NULL),
('hotel-006', 'Hotel Forum', 'Rome', 'https://static.cupid.travel/hotels/18367316.jpg', true, 8.3, 2482, 295.0, 41.89391, 12.48759, '<p><strong>Luxurious 4-Star Stay in the Heart of Rome</strong></p><p><strong>Elegant Rooms and Modern Amenities</strong>: Indulge in the lavish design of our rooms with luxurious fabrics, parquet floors, and comfortable beds. Stay entertained with satellite TV, stay refreshed with a minibar, and relax in a private bathroom with complimentary toiletries.</p><p><strong>Dining with a View</strong>: Enjoy Roman and international delicacies at our restaurant while taking in breathtaking views of the Eternal City from our terrace. Start your day with a generous breakfast on the rooftop terrace overlooking the city.</p><p><strong>Prime Location</strong>: Situated in an 18-century building opposite the Roman Forum, our hotel offers easy access to iconic landmarks like the Coliseum and Piazza Venezia. Explore the city effortlessly with Colosseo Metro Station just 500 meters away.</p><p>Book your unforgettable Roman getaway at Hotel Forum today!</p>', 204, 'Not Available', 'EUR', 'it', 'rome', 'Via Tor de'' Conti, 25', '00184', 'https://static.cupid.travel/hotels/18367316.jpg', 'https://static.cupid.travel/hotels/thumbnail/18367316.jpg', 4, '[16, 109, 3, 5, 15, 28, 48, 91, 49, 51, 81, 64, 44, 127, 143, 129, 124, 101, 176, 219, 205, 455, 451, 449, 462, 461, 425, 459, 467, 465, 468, 422, 456, 453, 454, 458, 486, 464, 418, 421, 420, 521, 540, 568, 584, 626, 675, 691, 692, 761, 784, 809, 828, 857, 1003, 1021, 1022, 1027, 1028]'::jsonb, '{"attributes": null, "showerChair": null, "entranceType": null, "petFriendly": "", "rampAngle": 0, "rampLength": 0, "entranceDoorWidth": 0, "roomMaxGuestsNumber": 0, "distanceFromTheElevatorToTheAccessibleRoom": 0}'::jsonb, NULL),
('hotel-007', 'Hotel Milani', 'Rome', 'https://static.cupid.travel/hotels/ex_8c5a72c4_z.jpg', true, 7.7, 111, 160.0, 41.90342, 12.50268, '<p>Escape to Hotel Milani, your enchanting retreat in the heart of Rome!</p><p><strong>Convenient Amenities:</strong> Enjoy complimentary wireless internet throughout the hotel, making it easy to stay connected. Our concierge services are here to ensure your every need is met, and unwind by the cozy fireplace in our welcoming lobby.</p><p><strong>Dining Delights:</strong> Start each day with a sumptuous buffet breakfast available daily from 7:00 AM to 10:00 AM. For the perfect indulgence, take advantage of our room service during limited hours, bringing delightful meals right to your room.</p><p><strong>Business &amp; Events:</strong> Hosting a meeting or event? Our flexible conference space spans 592 square feet, accommodating all your professional needs. With the added conveniences of a business center and multilingual staff, your experience will be seamless.</p><p>Book your stay at Hotel Milani today for an unforgettable Roman getaway!</p>', 204, 'Not Available', 'EUR', 'it', 'rome', 'Via Magenta 12', '9999', 'https://static.cupid.travel/hotels/ex_8c5a72c4_z.jpg', 'https://static.cupid.travel/hotels/thumbnail/ex_8c5a72c4_z.jpg', 3, '[1979, 2050, 2261, 2411, 107, 91, 124, 185, 502, 509, 513, 519, 521, 535, 540, 564, 581, 784, 827, 845, 846, 847, 854, 960, 987, 988, 992, 993, 994, 995, 996, 997, 998, 999, 1001, 1002, 1003, 1004]'::jsonb, '{"attributes": null, "showerChair": null, "entranceType": null, "petFriendly": "", "rampAngle": 0, "rampLength": 0, "entranceDoorWidth": 0, "roomMaxGuestsNumber": 0, "distanceFromTheElevatorToTheAccessibleRoom": 0}'::jsonb, NULL),
('hotel-008', 'SHG Hotel Portamaggiore', 'Rome', '', true, 0.0, 0, 120.0, 41.891342, 12.513917, '', 204, 'SHG Hotels', 'EUR', 'it', 'rome', 'Piazza di Porta Maggiore 25', '00185', '', '', 3, '[]'::jsonb, '{"attributes": null, "showerChair": null, "entranceType": null, "petFriendly": "", "rampAngle": 0, "rampLength": 0, "entranceDoorWidth": 0, "roomMaxGuestsNumber": 0, "distanceFromTheElevatorToTheAccessibleRoom": 0}'::jsonb, '2025-05-05T15:57:54Z'),
('hotel-009', 'Hotel Eden - Dorchester Collection', 'Rome', 'https://static.cupid.travel/hotels/321866375.jpg', true, 9.5, 110, 530.0, 41.90669, 12.48747, '<p><strong>Luxurious Accommodations</strong><br>Hotel Eden - Dorchester Collection offers luxury rooms with classic Italian furnishings, satellite LED TV, and city views. The perfect blend of comfort and elegance awaits you in each room.</p><p><strong>Culinary Excellence</strong><br>Indulge in gourmet Mediterranean cuisine at the award-winning La Terrazza restaurant with panoramic views. Pair your dinner with exquisite wines for a truly unforgettable dining experience. Additionally, enjoy lunch and dinner at Il Giardino Ristorante, and start your day with an extensive buffet breakfast.</p><p><strong>Prime Location</strong><br>Located near Via Veneto street and within walking distance to the Spanish Steps, Villa Borghese park, and the Trevi Fountain, our hotel provides the ideal base for exploring the beauty of Rome.</p><p>Experience luxury and sophistication at Hotel Eden - Dorchester Collection. Book your stay now to create unforgettable memories in the heart of Rome.</p>', 204, 'Dorchester Collection', 'EUR', 'it', 'rome', 'Via Ludovisi 49', '00187', 'https://static.cupid.travel/hotels/321866375.jpg', 'https://static.cupid.travel/hotels/thumbnail/321866375.jpg', 5, '[1814, 2261, 6848, 16, 109, 3, 5, 15, 28, 4, 48, 91, 49, 51, 81, 78, 64, 25, 44, 75, 55, 73, 53, 79, 108, 127, 124, 185, 101, 176, 188, 189, 222, 205, 218, 236, 226, 217, 231, 232, 455, 451, 449, 462, 457, 461, 425, 459, 467, 460, 465, 468, 422, 466, 453, 454, 424, 458, 486, 488, 418, 485, 487, 420, 463, 409, 413, 495, 521, 540, 568, 584, 675, 757, 761, 784, 806, 809, 828, 857, 880, 901, 966, 995, 1003, 1005]'::jsonb, '{"attributes": null, "showerChair": null, "entranceType": null, "petFriendly": "", "rampAngle": 0, "rampLength": 0, "entranceDoorWidth": 0, "roomMaxGuestsNumber": 0, "distanceFromTheElevatorToTheAccessibleRoom": 0}'::jsonb, NULL),
('hotel-010', 'Hotel Adriano', 'Rome', 'https://static.cupid.travel/hotels/67806065.jpg', true, 0.0, 0, 210.0, 41.90237, 12.47574, '<p><strong>Historic Charm and Modern Comfort</strong><br>Hotel Adriano, located in a 17th-century building in central Rome, seamlessly blends historic charm with modern comfort. Just a short stroll from iconic landmarks like the Pantheon and Via Del Corso, the hotel offers stylish, air-conditioned rooms with light color schemes and elegant furnishings.</p><p><strong>Luxurious Amenities</strong><br>Indulge in the luxurious amenities offered at Adriano Hotel, including minibars in every room and satellite TV with internet access. Whether you''re unwinding after a day of sightseeing or simply relaxing in your room, these amenities are designed to enhance your stay.</p><p><strong>Prime Location</strong><br>Conveniently situated 500 meters from Piazza Navona and a 15-minute walk to St Peter’s Basilica, Hotel Adriano''s prime location allows guests to explore Rome''s treasures with ease. Book your stay now and experience the perfect blend of history and comfort.</p>', 204, 'Not Available', 'EUR', 'it', 'rome', 'Via di Pallacorda, 2', '00186', 'https://static.cupid.travel/hotels/67806065.jpg', 'https://static.cupid.travel/hotels/thumbnail/67806065.jpg', 3, '[16, 109, 28, 48, 51, 44, 75, 108, 143, 129, 455, 451, 449, 462, 457, 461, 425, 460, 465, 468, 456, 452, 466, 458, 486, 464, 421, 411, 407, 409, 413, 495, 584, 642, 761, 784, 789, 806, 857, 880, 903, 932, 966, 1021, 1022]'::jsonb, '{"attributes": null, "showerChair": null, "entranceType": null, "petFriendly": "", "rampAngle": 0, "rampLength": 0, "entranceDoorWidth": 0, "roomMaxGuestsNumber": 0, "distanceFromTheElevatorToTheAccessibleRoom": 0}'::jsonb, NULL),
('hotel-011', 'Hotel Mecenate Palace', 'Rome', 'https://static.cupid.travel/hotels/22725330.jpg', true, 8.6, 2331, 275.0, 41.89681, 12.49992, '<p><strong>Luxurious Accommodation</strong><br>Experience elegance and comfort at The Mecenate Palace, a 4-star hotel in the heart of Rome. The rooms are beautifully designed, equipped with air conditioning, and feature tea/coffee makers. Some rooms even offer breathtaking panoramic views of the Eternal City.</p><p><strong>Spectacular Dining Experience</strong><br>Indulge in a culinary journey at the Roof Garden Restaurant and Sky Bar, where you can enjoy delicious meals while overlooking the iconic rooftops of Rome. The stunning views of the Basilica of Santa Maria Maggiore add a touch of magic to your dining experience.</p><p><strong>Convenient Location</strong><br>Located just a short walk from Rome Termini Metro and Train Station, Hotel Mecenate Palace offers easy access to the city''s top attractions. Within 15 minutes, you can reach must-see landmarks such as the Coliseum and the Roman Forum.</p><p>Ready to immerse yourself in luxury and convenience? Book your stay at The Mecenate Palace now.</p>', 204, 'Not Available', 'EUR', 'it', 'rome', 'Via Carlo Alberto 3', '00185', 'https://static.cupid.travel/hotels/22725330.jpg', 'https://static.cupid.travel/hotels/thumbnail/22725330.jpg', 4, '[16, 109, 3, 5, 15, 48, 91, 49, 51, 81, 64, 25, 44, 108, 127, 129, 124, 176, 455, 451, 449, 462, 457, 461, 425, 459, 467, 460, 465, 468, 422, 456, 452, 466, 453, 419, 454, 424, 458, 486, 464, 488, 418, 485, 421, 487, 521, 540, 568, 584, 691, 692, 761, 784, 809, 828, 1003, 1021, 1022, 1027, 1028]'::jsonb, '{"attributes": null, "showerChair": null, "entranceType": null, "petFriendly": "", "rampAngle": 0, "rampLength": 0, "entranceDoorWidth": 0, "roomMaxGuestsNumber": 0, "distanceFromTheElevatorToTheAccessibleRoom": 0}'::jsonb, NULL),
('hotel-012', 'Bettoja Hotel Massimo D''Azeglio', 'Rome', 'https://static.cupid.travel/hotels/ex_85beae0e_z.jpg', true, 9.0, 118, 240.0, 41.900066, 12.498982, '<p><strong>Convenient Amenities:</strong><br>Enjoy complimentary wireless internet access, concierge services, and discounted access to a nearby fitness facility during your stay at Bettoja Hotel Massimo D''Azeglio.</p><p><strong>Delectable Dining Options:</strong><br>Indulge in Italian cuisine at the on-site restaurant, Massimo D''azeglio, or opt for room service (during limited hours) while savoring your favorite drink at the bar/lounge.</p><p><strong>Comfortable Accommodations:</strong><br>Relax in one of the 185 uniquely decorated guestrooms equipped with modern amenities, such as minibars, flat-screen TVs, and free Wi-Fi, ensuring a cozy and connected stay.</p><p>Immerse yourself in the heart of Rome''s charm and elegance by booking your stay at Bettoja Hotel Massimo D''Azeglio. Enhance your travel experience with our top-notch services and prime location for exploring the enchanting city.</p>', 204, 'Not Available', 'EUR', 'it', 'rome', 'Via Cavour 18', '00184', 'https://static.cupid.travel/hotels/ex_85beae0e_z.jpg', 'https://static.cupid.travel/hotels/thumbnail/ex_85beae0e_z.jpg', 4, '[1091, 2020, 2247, 2253, 2259, 107, 8, 91, 124, 491, 497, 519, 533, 536, 561, 569, 581, 623, 626, 675, 678, 691, 827, 987, 997, 999, 1003, 1006, 1007, 1008, 1009, 1011, 1012]'::jsonb, '{"attributes": null, "showerChair": null, "entranceType": null, "petFriendly": "", "rampAngle": 0, "rampLength": 0, "entranceDoorWidth": 0, "roomMaxGuestsNumber": 0, "distanceFromTheElevatorToTheAccessibleRoom": 0}'::jsonb, NULL),
('hotel-013', 'Bettoja Hotel Atlantico', 'Rome', 'https://static.cupid.travel/hotels/26902487.jpg', true, 8.7, 401, 230.0, 41.89998, 12.49881, '<p><strong>Historic Charm on Rome''s Highest Hill</strong></p><p><strong>Convenient Location</strong>: Situated steps away from Termini Train Station, Bettoja Atlantico offers easy access to Rome''s iconic landmarks like the Coliseum and Trevi Fountain within a short walk.</p><p><strong>Breathtaking Views</strong>: Enjoy stunning panoramic views of Rome from the hotel''s rooftop terrace, providing a picturesque backdrop to your stay.</p><p><strong>Comfortable Accommodation</strong>: Relax in guest rooms featuring classic decor, air conditioning, and modern amenities like a TV, safe, and minibar.</p><p>Experience the perfect blend of history and modern comfort at Bettoja Atlantico. Book now to secure your unforgettable Roman getaway.</p>', 204, 'Not Available', 'EUR', 'it', 'rome', 'Via Cavour 23', '00184', 'https://static.cupid.travel/hotels/26902487.jpg', 'https://static.cupid.travel/hotels/thumbnail/26902487.jpg', 4, '[6848, 109, 3, 5, 4, 48, 91, 51, 81, 64, 44, 75, 176, 219, 205, 455, 451, 449, 462, 457, 461, 459, 467, 456, 466, 453, 419, 454, 458, 486, 464, 488, 487, 495, 540, 584, 626, 675, 757, 761, 784, 809, 828, 857, 880]'::jsonb, '{"attributes": null, "showerChair": null, "entranceType": null, "petFriendly": "", "rampAngle": 0, "rampLength": 0, "entranceDoorWidth": 0, "roomMaxGuestsNumber": 0, "distanceFromTheElevatorToTheAccessibleRoom": 0}'::jsonb, NULL),
('hotel-014', 'Bettoja Hotel Mediterraneo', 'Rome', 'https://static.cupid.travel/hotels/165399886.jpg', true, 8.8, 1573, 255.0, 41.90035, 12.4991, '<p><strong>Panoramic Roof Terrace with Stunning Rome Views</strong></p><p><strong>Luxurious Rooms and Suites</strong><br>Indulge in the elegant and classically styled rooms at Bettoja Hotel Mediterraneo. Enjoy free Wi-Fi, air conditioning, and spacious accommodations with large windows and high ceilings. Upgrade to a suite for a private terrace and the possibility of a relaxing spa bath experience.</p><p><strong>Delicious Breakfast and All-day Bar</strong><br>Start your day with a generous breakfast featuring freshly baked pastries and seasonal fruits. Throughout the day, unwind at the hotel''s bar offering a variety of drinks and hot/cold snacks to keep you satisfied.</p><p>Experience the charm of Rome from a prime location just a short walk from Roma Termini Train Station. Book your stay at Bettoja Hotel Mediterraneo for an unforgettable Roman getaway.</p>', 204, 'Not Available', 'EUR', 'it', 'rome', 'Via Cavour 15', '00184', 'https://static.cupid.travel/hotels/165399886.jpg', 'https://static.cupid.travel/hotels/thumbnail/165399886.jpg', 4, '[6848, 16, 109, 3, 5, 28, 4, 48, 91, 51, 81, 64, 25, 44, 75, 73, 53, 129, 124, 185, 176, 183, 188, 189, 219, 205, 213, 455, 451, 449, 462, 457, 461, 425, 459, 467, 465, 468, 422, 456, 452, 466, 453, 454, 458, 486, 464, 488, 418, 487, 420, 409, 495, 497, 521, 540, 584, 626, 675, 691, 692, 757, 761, 784, 809, 828, 857, 880, 966, 1003, 1005, 1021, 1022, 1027, 1028]'::jsonb, '{"attributes": null, "showerChair": null, "entranceType": null, "petFriendly": "", "rampAngle": 0, "rampLength": 0, "entranceDoorWidth": 0, "roomMaxGuestsNumber": 0, "distanceFromTheElevatorToTheAccessibleRoom": 0}'::jsonb, NULL),
('hotel-015', 'Hotel Traiano', 'Rome', 'https://static.cupid.travel/hotels/527231792.jpg', true, 8.3, 1353, 245.0, 41.89643, 12.4861, '<p><strong>Luxurious Accommodation in the Heart of Rome</strong></p><p><strong>Prime Location</strong>: Hotel Traiano is ideally situated in Rome, offering stunning views of the Roman Fora and just a stone''s throw away from iconic landmarks like the Capitol and Coliseum.</p><p><strong>Elegant Dining Experience</strong>: Indulge in a delicious breakfast spread at the hotel''s elegant dining room, featuring a variety of options from croissants and eggs to Italian coffee and cappuccino, all served amidst beautiful paintings and chandeliers.</p><p><strong>Exceptional Service and Convenience</strong>: With a 24-hour available staff ready to assist with restaurant recommendations and city excursions, along with proximity to Rome Termini Station and the Trevi Fountain, Hotel Traiano ensures a comfortable and memorable stay for all guests.</p><p>Book now to experience the charm and luxury of Hotel Traiano in the heart of Rome.</p>', 204, '4L Collection', 'EUR', 'it', 'rome', 'Via Quattro Novembre 154', '00187', 'https://static.cupid.travel/hotels/527231792.jpg', 'https://static.cupid.travel/hotels/thumbnail/527231792.jpg', 4, '[16, 109, 5, 28, 4, 48, 91, 49, 51, 81, 78, 64, 44, 108, 143, 129, 124, 101, 218, 425, 422, 495, 521, 540, 568, 584, 691, 692, 761, 784, 809, 1021, 1022, 1027, 1028]'::jsonb, '{"attributes": null, "showerChair": null, "entranceType": null, "petFriendly": "", "rampAngle": 0, "rampLength": 0, "entranceDoorWidth": 0, "roomMaxGuestsNumber": 0, "distanceFromTheElevatorToTheAccessibleRoom": 0}'::jsonb, NULL),
('hotel-016', 'Hotel Villa Pamphili Roma', 'Rome', 'https://static.cupid.travel/hotels/308378654.jpg', true, 8.7, 5165, 215.0, 41.88215, 12.43224, '<p><strong>Luxurious Accommodation</strong><br>Hotel Villa Pamphili Roma, located in Rome, offers air-conditioned rooms with modern amenities including a flat-screen TV and private bathroom.</p><p><strong>Delicious Dining Options</strong><br>Guests can enjoy a variety of dining choices at the hotel''s restaurant, serving Italian, Mediterranean, and Seafood cuisine with options for vegetarians, dairy-free, and vegans.</p><p><strong>Relaxing Facilities</strong><br>Unwind at the seasonal outdoor swimming pool, fitness centre, and garden, or explore the city with bike and car hire services available.</p><p>Book your stay at Hotel Villa Pamphili Roma for a memorable experience in Rome.</p>', 204, 'Not Available', 'EUR', 'it', 'rome', 'Via Della Nocetta 105', '00164', 'https://static.cupid.travel/hotels/308378654.jpg', 'https://static.cupid.travel/hotels/thumbnail/308378654.jpg', 4, '[1814, 2413, 6848, 16, 109, 301, 3, 5, 15, 28, 4, 48, 91, 49, 51, 81, 78, 64, 25, 44, 63, 75, 10, 55, 73, 50, 108, 127, 143, 170, 129, 124, 185, 176, 188, 189, 222, 219, 205, 218, 236, 241, 226, 231, 232, 256, 455, 451, 449, 462, 457, 461, 425, 459, 467, 460, 465, 468, 422, 456, 452, 466, 453, 419, 454, 424, 458, 486, 464, 488, 418, 485, 421, 487, 420, 463, 411, 407, 413, 495, 497, 521, 540, 568, 584, 626, 631, 658, 675, 691, 692, 708, 712, 714, 725, 757, 761, 784, 789, 809, 828, 835, 856, 857, 859, 901, 916, 932, 966, 967, 1003, 1005, 1021, 1022, 1027, 1028]'::jsonb, '{"attributes": null, "showerChair": null, "entranceType": null, "petFriendly": "", "rampAngle": 0, "rampLength": 0, "entranceDoorWidth": 0, "roomMaxGuestsNumber": 0, "distanceFromTheElevatorToTheAccessibleRoom": 0}'::jsonb, NULL)
